// A scene per card: background + what the card does. Functions of u (id suffix).
const { BG: BG3, X, img, put, palm, clouds } = require('./art3.cjs');
const { BG: BG4, halo, lantern, motes } = require('./bg4.cjs'); const { SCENE, P: P1 } = require('./art.cjs'); Object.assign(P1, require('./pieces4.cjs'));
const BG = { ...BG3, ...BG4 };
const { SHIPS, afloat, shadow, belfry, woodTex, stoneTex } = require('./helpers4.cjs');
const i = (k, x, y, s, r = 0, u) => SHIPS.has(k) && Math.abs(r) <= 6 ? afloat(k, x, y, s, r, u) : r === 180 ? img(k, x, y, s, r, u).replace(/filter="url\(#drop[^)]*\)"/, '') : img(k, x, y, s, r, u);
const sh = shadow;
