const smoke = (u, x, y, s = 1) => p('smokeP', x, y, s, 0, u, false);
const fire = (u, x, y, s = 1) => p('fireP', x, y, s, 0, u, false);
const glow = (u, x, y, s = 1) => p('glowP', x, y, s, 0, u, false);
const arc = (x1, y1, x2, y2, h, col = '#fff6d6') => `<path d="M${x1} ${y1}Q${(x1 + x2) / 2} ${Math.min(y1, y2) - h} ${x2} ${y2}" stroke="${col}" stroke-width="1" fill="none" stroke-dasharray="3 2.5" opacity=".9"/>`;
