const net = (x, y, w, h) => `<g opacity=".8">${Array.from({ length: 7 }, (_, k) => `<path d="M${x + k * w / 6} ${y}q${w / 12} ${h / 2} 0 ${h}" stroke="#c9a878" stroke-width=".7" fill="none"/>`).join('')}${Array.from({ length: 5 }, (_, k) => `<path d="M${x} ${y + k * h / 4}q${w / 2} 4 ${w} 0" stroke="#c9a878" stroke-width=".7" fill="none"/>`).join('')}</g>`;
const keg = (u, x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})" filter="url(#drop${u})"><path d="M-12 -16q-5 16 0 32h24q5 -16 0 -32z" fill="url(#oak${u})" stroke="#2a1608"/><path d="M-15 -8h30M-15 8h30" stroke="url(#iron${u})" stroke-width="2.4"/><path d="M-4 -16v32" stroke="#3a2410" stroke-width=".6"/></g>`;
