const lanternHang = u => `<g filter="url(#drop${u})"><path d="M0 -40v12" stroke="#3a2a1a" stroke-width="1"/><circle cx="0" cy="-14" r="22" fill="url(#glow${u})"/>${i('lantern', 0, -14, .45, 0, u)}</g>`;
