const contract = (u, x, y, r = -4, blood = false, title = 'ДОГОВОР') => `<g transform="translate(${x} ${y}) rotate(${r})" filter="url(#drop${u})"><rect x="-22" y="-26" width="44" height="52" fill="#f4e8cc" stroke="#8a6a3a" stroke-width=".6"/><text x="0" y="-16" font-family="Alegreya SC,serif" font-size="4.6" text-anchor="middle" fill="#2a1a0a">${title}</text>${[-10, -6, -2, 2, 6, 10].map(yy => `<path d="M-16 ${yy}h${yy > 6 ? 18 : 32}" stroke="#7a6a52" stroke-width=".5"/>`).join('')}<path d="M-14 18q6 -6 10 0t10 -2" stroke="${blood ? '#9a1a12' : '#2a1a0a'}" stroke-width="1" fill="none"/>${blood ? '<circle cx="12" cy="20" r="2" fill="#9a1a12"/><path d="M12 22q1 3 0 4" stroke="#9a1a12" stroke-width="1"/>' : ''}</g>`;
const crown = (u, x, y) => `<g transform="translate(${x} ${y})"><circle r="12" fill="url(#red${u})"/><circle r="8" fill="none" stroke="#e08070" stroke-width=".8"/><path d="M-4 1l1 -5 3 3 3 -3 1 5z" fill="#e08070"/></g>`;
const towerChain = u => `<path d="M0 86q50 10 100 2t100 4" stroke="#141618" stroke-width="5" fill="none"/>${Array.from({ length: 20 }, (_, k) => `<ellipse cx="${k * 10 + 5}" cy="${88 + Math.sin(k / 3) * 2}" rx="5" ry="2.6" fill="none" stroke="url(#iron${u})" stroke-width="2"/>`).join('')}`;
const hullWall = u => `<rect x="0" y="0" width="200" height="120" fill="#3a3226"/>${Array.from({ length: 10 }, (_, k) => `<path d="M0 ${k * 12}h200" stroke="#1a140e" stroke-width="1.4"/><path d="M0 ${k * 12 + 1.6}h200" stroke="#6a5a44" stroke-width=".5" opacity=".6"/>`).join('')}`;

// ---- fourth pass scene parts
const rivets = (x, y1, y2, step = 6) => Array.from({ length: Math.floor((y2 - y1) / step) + 1 }, (_, k) => `<circle cx="${x}" cy="${y1 + k * step}" r=".9" fill="#c8ccd0" stroke="#2a2c2e" stroke-width=".3"/>`).join('');
function hullSide(u, o = {}) {
  const top = 28, wl = 98, ports = o.ports || [];
  let s = BG.seaDay(u, { ships: false }) + `<rect x="0" y="${top - 4}" width="200" height="${wl - top + 4}" fill="#24140a"/>`
    + woodTex(u, 0, top, 200, wl - top, o.armour ? '#5e3a1e' : '#86532a', o.armour ? '#2a1a0c' : '#4a2a12', '#1a0c04', o.armour ? 6 : 7, false, 31)
    + `<rect x="0" y="${top - 5}" width="200" height="5" fill="url(#oak${u})"/><rect x="0" y="${top - 5}" width="200" height=".8" fill="#e8b880" opacity=".6"/>
       <rect x="0" y="${top + 6}" width="200" height="4" fill="#1a0c04"/><rect x="0" y="${top + 6}" width="200" height=".6" fill="#c08a52" opacity=".5"/>
       <rect x="0" y="86" width="200" height="5" fill="#140a04"/><rect x="0" y="86" width="200" height=".6" fill="#a87444" opacity=".5"/>
       <rect x="0" y="91" width="200" height="${wl - 91}" fill="#2a3a30" opacity=".35"/>`;
  if (o.armour) s += [12, 70, 130, 188].map(x => `<rect x="${x - 3}" y="${top}" width="6" height="${86 - top}" fill="url(#ironH${u})" stroke="#0e1012" stroke-width=".4"/>${rivets(x, top + 3, 84)}`).join('');
  for (const [kind, x] of ports) {
    const y = 58, W = 30, Hh = 22;
    if (kind === 'closed') { s += `<rect x="${x - W / 2 - 2}" y="${y - Hh / 2 - 2}" width="${W + 4}" height="${Hh + 4}" fill="#1a0c04"/><rect x="${x - W / 2}" y="${y - Hh / 2}" width="${W}" height="${Hh}" fill="url(#red${u})" stroke="#3a0a06" stroke-width=".6"/>${[-7, 0, 7].map(d => `<path d="M${x - W / 2} ${y + d}h${W}" stroke="#5a140c" stroke-width=".5" opacity=".7"/>`).join('')}
      <rect x="${x - W / 2 + 2}" y="${y - Hh / 2 + 1}" width="8" height="2.4" fill="url(#iron${u})"/><rect x="${x + W / 2 - 10}" y="${y - Hh / 2 + 1}" width="8" height="2.4" fill="url(#iron${u})"/><circle cx="${x}" cy="${y + 4}" r="2.4" fill="none" stroke="url(#iron${u})" stroke-width="1"/>`; continue; }
    const hit = kind === 'hit';
    s += `<path d="M${x - W / 2 - 3} ${y - Hh / 2 - 3}h${W + 6}l-3 -6h${-W}z" fill="url(#red${u})" stroke="#3a0a06" stroke-width=".6" ${hit ? `transform="rotate(-24 ${x - W / 2} ${y - Hh / 2})"` : ''}/>
      <rect x="${x - W / 2 - 2}" y="${y - Hh / 2 - 2}" width="${W + 4}" height="${Hh + 4}" fill="#1a0c04"/><rect x="${x - W / 2}" y="${y - Hh / 2}" width="${W}" height="${Hh}" fill="#0a0604"/>
      <path d="M${x - W / 2} ${y - Hh / 2}l4 4h${W - 8}l4 -4M${x - W / 2} ${y + Hh / 2}l4 -4h${W - 8}l4 4" fill="#6a1a10" stroke="#3a0a06" stroke-width=".4"/>`;
    if (!hit) s += `<g filter="url(#drop${u})"><circle cx="${x}" cy="${y + 1}" r="7.6" fill="url(#iron${u})" stroke="#0a0c0e" stroke-width=".6"/><circle cx="${x}" cy="${y + 1}" r="5.6" fill="none" stroke="#5a6064" stroke-width=".6"/><circle cx="${x}" cy="${y + 1}" r="3.6" fill="#050505"/><path d="M${x - 5} ${y - 3}q3 -2.4 6 -2.4" stroke="#c8d0d4" stroke-width=".7" fill="none" opacity=".7"/></g>`;
    else s += `<circle cx="${x}" cy="${y}" r="26" fill="url(#glow${u})"/>${p('fireP', x - 2, y + 2, .55, 0, u, false)}
      ${(() => { const pts = Array.from({ length: 22 }, (_, k) => { const t = k / 22 * Math.PI * 2, j = k % 2 ? 1 : .78 + (k % 5) * .06; return `${(x + Math.cos(t) * (W / 2 + 9) * j).toFixed(1)} ${(y + Math.sin(t) * (Hh / 2 + 8) * j).toFixed(1)}`; }); return `<path d="M${pts.join('L')}zM${x - W / 2} ${y - Hh / 2}v${Hh}h${W}v${-Hh}z" fill="#160904" fill-rule="evenodd" opacity=".92"/><path d="M${pts.join('L')}z" fill="none" stroke="#e8a060" stroke-width=".5" opacity=".5"/>`; })()}
      
      ${[[-1, -1, 14, -12], [1, -1, 16, -8], [1, 1, 12, 10], [-1, 1, 15, 6], [0, -1, 2, -16]].map(([sx, sy, dx, dy]) => `<path d="M${x + sx * (W / 2 + 2)} ${y + sy * (Hh / 2)}l${sx ? sx * dx : 3} ${dy}l2 1z" fill="#c8945a" stroke="#4a2a12" stroke-width=".4"/>`).join('')}
      <ellipse cx="${x + 2}" cy="${y + 3}" rx="7" ry="4.8" fill="url(#iron${u})" transform="rotate(30 ${x} ${y})" opacity=".9"/>
      ${p('smokeP', x + 6, y - 22, .7, 0, u, false)}`;
  }
  s += `<linearGradient id="hr${u}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#04121a" stop-opacity=".75"/><stop offset="1" stop-color="#04121a" stop-opacity="0"/></linearGradient><rect x="0" y="${wl}" width="200" height="14" fill="url(#hr${u})"/>
    <path d="M0 ${wl + .4}q25 1.6 50 0t50 0t50 0t50 0" stroke="#f4fcff" stroke-width="1.1" fill="none" opacity=".85"/><path d="M0 ${wl + 3}q30 1.6 60 0t60 .4t80 -.4" stroke="#ffffff" stroke-width=".5" fill="none" opacity=".5"/>`;
  return s;
}
const dent = (u, x, y) => `<circle cx="${x}" cy="${y}" r="5.4" fill="#120804" opacity=".7"/><circle cx="${x - .8}" cy="${y - .8}" r="4" fill="#3a2414"/><path d="M${x - 3} ${y - 3.6}a4.4 4.4 0 0 1 6 .4" stroke="#c08a52" stroke-width=".6" fill="none"/>${[[9, -3], [7, 6], [-8, 5], [-6, -7], [2, 9]].map(([dx, dy]) => `<path d="M${x} ${y}l${dx * .6} ${dy * .6}l${dx * .4} ${dy * .4 + 1}" stroke="#140804" stroke-width=".6" fill="none"/>`).join('')}`;
